def architecture_report(a):return {"confidence":a.confidence,"evidence":list(a.evidence),"rails":{k:{"voltage":v.voltage,"components":list(v.components),"confidence":v.confidence} for k,v in sorted(a.rails.items())},"stages":[{"component_id":s.component_id,"kind":s.kind,"input_rails":list(s.input_rails),"output_rails":list(s.output_rails),"enable_nets":list(s.enable_nets),"feedback_nets":list(s.feedback_nets),"confidence":s.confidence} for s in a.stages],"dependencies":len(a.dependencies),"sequences":len(a.sequences),"decoupling_groups":len(a.decoupling)}
